const optimizedText = $json.optimized_text;

// Împarte textul în blocuri pe baza titlurilor, listelor și paragrafelor.
const blocks = optimizedText.split(/^(#+ .+\n\n)|(\n\n)|(^- .+\n)|(^\d+\. .+\n)/gm).filter(Boolean);

const notionBlocks = blocks.map(block => {
  if (!block || block.trim().length === 0) {
    return null; 
  }

  const cleanBlock = block.trim();

  // HEADING 1, 2, 3
  if (cleanBlock.startsWith('# ')) {
    return { "type": "heading_1", "heading_1": { "rich_text": [ { "text": { "content": cleanBlock.replace('# ', '').trim() } } ] } };
  } else if (cleanBlock.startsWith('## ')) {
    return { "type": "heading_2", "heading_2": { "rich_text": [ { "text": { "content": cleanBlock.replace('## ', '').trim() } } ] } };
  } else if (cleanBlock.startsWith('### ')) {
    return { "type": "heading_3", "heading_3": { "rich_text": [ { "text": { "content": cleanBlock.replace('### ', '').trim() } } ] } };
  } 
  // BULLETED LIST
  else if (cleanBlock.startsWith('- ')) {
    return { "type": "bulleted_list_item", "bulleted_list_item": { "rich_text": [ { "text": { "content": cleanBlock.replace('-', '').trim() } } ] } };
  } 
  // NUMBERED LIST
  else if (cleanBlock.match(/^\d+\. /)) {
    return { "type": "numbered_list_item", "numbered_list_item": { "rich_text": [ { "text": { "content": cleanBlock.replace(/^\s*\d+[.).]\s*/, '').trim() } } ] } };
  } 
  // PARAGRAPH (Fallback)
  else {
    return { "type": "paragraph", "paragraph": { "rich_text": [ { "text": { "content": cleanBlock } } ] } };
  }
}).filter(Boolean); 


// NOU: CONSOLIDEAZĂ ȘI STRINGIFY
// -------------------------------------------------------------------

// 1. Construim Body-ul JSON final (care include array-ul de blocuri)
const finalBody = {
    "children": notionBlocks // notionBlocks este array-ul cu toate cele 42 de blocuri
};

// 2. Returnăm un singur item care conține Body-ul stringified (gata de HTTP Request)
return [
    {
        json: {
            // Body-ul JSON COMPLET, ca string
            bodyString: JSON.stringify(finalBody)
        }
    }
];

