const item = $json;
const pageProperties = item.properties;

// Funcție ajutătoare pentru extragerea textului din proprietățile de tip Rich Text/Title
const getPlainText = (property) => {
    // Adaugă o verificare inițială pentru a preveni erorile dacă proprietatea lipsește
    if (!property) {
        return '';
    }

    // Verifică dacă proprietatea are câmpuri title sau rich_text
    if (property.title && property.title.length > 0) {
        return property.title[0].plain_text;
    }
    if (property.rich_text && property.rich_text.length > 0) {
        return property.rich_text[0].plain_text;
    }
    return '';
};

// Extragerea proprietăților Rich Text (Titlu, Descriere, Keyphrase)
const seoTitle = getPlainText(pageProperties['SEO Title']);
const metaDescription = getPlainText(pageProperties['Meta Description']);
const focusKeyphrase = getPlainText(pageProperties['Focus Keyphrase']);
const socialHook = getPlainText(pageProperties['Social Hook']);

// Extragerea URL-ului imaginii din proprietatea 'URL Image'
let imageUrl = '';
const urlProperty = pageProperties['URL Image'];

// Verifică dacă proprietatea URL există și are o valoare
if (urlProperty && urlProperty.url) {
    imageUrl = urlProperty.url;
}

// --- Extragerea și formatarea Tag-urilor (Multi-select) ---
// Extrage lista de obiecte tag din structura Notion.
const tagsArray = pageProperties.Tags.multi_select; // Această linie lipsea!

// Creează un ARRAY de string-uri (Numele tagurilor) pentru a fi trimise către WordPress
const keywordsString = tagsArray.map(tag => tag.name).join(','); // FĂRĂ spațiu


// Extragem URL-ul paginii
const pageUrl = item.url;

// Returnăm un obiect JSON curat cu proprietățile extrase
return [
  {
    json: {
      seo_title: seoTitle,
      meta_description: metaDescription,
      focus_keyphrase: focusKeyphrase,
      keywords: keywordsString, // Trimitem ARRAY-ul
      notion_page_url: pageUrl,
      social_hook: socialHook,
      image_url: imageUrl 
    }
  }
];

const text = $json.text;

// Regex pentru a extrage JSON dintr-un bloc ```json ... ```
const jsonRegex = /```json\s*([\s\S]*?)\s*```/;
const match = jsonRegex.exec(text);

// Dacă există bloc de cod, iau doar interiorul, altfel iau tot textul
let jsonString = match ? match[1] : text;

try {
  const parsedJson = JSON.parse(jsonString);
  return [
    {
      json: parsedJson
    }
  ];
} catch (e) {
  console.error("Eroare la parsarea JSON:", e.message);
  return [
    {
      json: {}
    }
  ];
}

const blocks = $json.blocks;

// Funcție recursivă pentru a extrage textul din blocuri, inclusiv cele imbricate
const extractTextFromBlocks = (blockArray) => {
  return blockArray.map(block => {
    const blockType = block.type;
    let plainText = '';

    // Extrage textul din blocurile cu proprietatea 'text'
    if (block[blockType] && block[blockType].text && block[blockType].text.length > 0) {
      plainText = block[blockType].text.map(item => item.plain_text).join('');
    }

    // Procesează blocurile 'to_do' și 'toggle'
    if (block.type === 'to_do' && block.to_do.text) {
        plainText = block.to_do.text.map(item => item.plain_text).join('');
    } else if (block.type === 'toggle' && block.toggle.text) {
        plainText = block.toggle.text.map(item => item.plain_text).join('');
    }

    // Verifică blocurile copil pentru conținut imbricat
    let childText = '';
    if (block[blockType] && block[blockType].children && block[blockType].children.length > 0) {
      childText = extractTextFromBlocks(block[blockType].children).join('\n\n');
    }

    // Formatează textul extras și îl returnează
    switch (blockType) {
      case 'heading_1':
      case 'heading_2':
      case 'heading_3':
        return `### ${plainText}\n${childText}`;
      case 'paragraph':
      case 'bulleted_list_item':
      case 'numbered_list_item':
      case 'callout':
      case 'quote':
      case 'to_do':
      case 'toggle':
        return `${plainText}\n${childText}`;
      case 'divider':
        return '---';
      case 'image':
        return '[imagine]';
      case 'child_page':
        return `[link către pagina copil: ${plainText}]`;
      default:
        console.warn(`Tip de bloc neprocesat: ${blockType}`);
        return '';
    }
  }).filter(Boolean).join('\n\n');
};

const textContent = extractTextFromBlocks(blocks);

return [
  {
    json: {
      content: textContent,
    }
  }
];

